import{_ as e,o as i,c as t,ag as n}from"./chunks/framework.CrXGS008.js";const w=JSON.parse('{"title":"Własność","description":"","frontmatter":{},"headers":[],"relativePath":"pl/repair-station-business/ownership.md","filePath":"pl/repair-station-business/ownership.md"}'),s={name:"pl/repair-station-business/ownership.md"};function o(r,a,c,p,z,d){return i(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="własnosc" tabindex="-1">Własność <a class="header-anchor" href="#własnosc" aria-label="Permalink to &quot;Własność&quot;">​</a></h1><h2 id="wystawienie-stacji-na-sprzedaz" tabindex="-1">Wystawienie stacji na sprzedaż <a class="header-anchor" href="#wystawienie-stacji-na-sprzedaz" aria-label="Permalink to &quot;Wystawienie stacji na sprzedaż&quot;">​</a></h2><p>Kupić można tylko stacje wystawione na sprzedaż. Jako admin z <code>nay_repair_business.config</code>:</p><ol><li>Utwórz stacje w <a href="/pl/repair-station/stations">edytorze Repair Station</a>.</li><li>Otwórz panel administratora przez <code>/nay:repairbusiness</code> albo akcję <strong>Zarządzaj stacjami na sprzedaż</strong> w <code>/nay</code>.</li><li>Wybierz stację, wpisz cenę sprzedaży i naciśnij <strong>Wystaw na sprzedaż</strong>.</li></ol><p>Ta sama lista jest w <code>/nay</code> jako <strong>Stacje na sprzedaż</strong>. Stacja na sprzedaż ma blip na mapie i podpowiedź z ceną. Dopóki nie ma właściciela, <strong>Stacje na sprzedaż bez właściciela</strong> decyduje, czy zostaje otwarta (gracze naprawiają tam jak zwykle), czy jest zamknięta do czasu zakupu. Stacji wyłączonej w Repair Station nie można kupić i nie ma ona blipa.</p><h2 id="zakup" tabindex="-1">Zakup <a class="header-anchor" href="#zakup" aria-label="Permalink to &quot;Zakup&quot;">​</a></h2><p>Gracz podchodzi do stacji i naciska <strong>E</strong>. Potwierdzenie pokazuje cenę i konto, z którego płaci (<strong>Konto zakupu</strong>). Gracz może mieć do <strong>Stacje na gracza</strong> stacji. Serwer sprawdza zakup, z odległości najwyżej 8 metrów od stacji, i zwraca pieniądze, jeśli coś się nie powiedzie.</p><h2 id="tablet" tabindex="-1">Tablet <a class="header-anchor" href="#tablet" aria-label="Permalink to &quot;Tablet&quot;">​</a></h2><p>Właściciel naciska <strong>E</strong> przy stacji, aby otworzyć tablet, z odległości 8 metrów lub mniej:</p><ul><li><strong>Przegląd</strong>: magazyn, kasa, naprawy z dzisiaj i z ostatnich 7 dni, ostatnie operacje.</li><li><strong>Magazyn</strong>: kup części lub oddaj przedmioty, zobacz <a href="/pl/repair-station-business/stock">Magazyn</a>.</li><li><strong>Kasa</strong>: wypłać pieniądze do gotówki lub banku albo wpłać pieniądze z banku do kasy.</li><li><strong>Ustawienia</strong>: procent cen, nazwa stacji, sprzedaż stacji.</li></ul><p>Nazwa wybrana przez właściciela zastępuje nazwę stacji w menu napraw. Procent zmienia cenę każdej usługi: gracze widzą cenę końcową przed zapłatą, a podatek (<strong>Podatek</strong>) jest pobierany od każdej płatności, reszta trafia do kasy.</p><h2 id="sprzedaz-i-utrata-stacji" tabindex="-1">Sprzedaż i utrata stacji <a class="header-anchor" href="#sprzedaz-i-utrata-stacji" aria-label="Permalink to &quot;Sprzedaż i utrata stacji&quot;">​</a></h2><ul><li><strong>Sprzedaż</strong>: właściciel dostaje na konto bankowe procent <strong>Odkup</strong> ceny zakupu plus kasę. Stacja wraca na sprzedaż za swoją cenę, chyba że personel zdjął ją ze sprzedaży.</li><li><strong>Usunięcie właściciela</strong>: personel może usunąć właściciela z panelu administratora. Dostaje zapłatę jak przy sprzedaży.</li><li><strong>Nieaktywność</strong>: właściciel, który nie otworzy tabletu przez <strong>Limit nieaktywności</strong> dni, traci stację i dostaje zapłatę jak przy sprzedaży. 0 wyłącza ten limit.</li><li><strong>Usunięta stacja</strong>: gdy stacja zostanie usunięta w edytorze Repair Station, jej właściciel dostaje zapłatę jak przy sprzedaży, a stacja znika z systemu.</li></ul><p>Właściciel offline w tym momencie dostaje pieniądze jednorazowo, przy następnym wczytaniu postaci, wraz z powiadomieniem. Każda operacja trafia do rejestru, który można odczytać przez <a href="/pl/repair-station-business/api">API</a>.</p>',14)])])}const u=e(s,[["render",o]]);export{w as __pageData,u as default};
